/**
 * 在实库上跑共用套件。EQTS_HANA_URL 形如 hana://SYSTEM:密码@127.0.0.1:39041，未设置时跳过。表建在 EQTS 模式里，每个用例重建。
 */
import { after, describe, it } from 'node:test'
import { createDb, type Statement } from '@eqts/core'
import { schema, type TestEnv } from '../../core/test/fixture.ts'
import { liveSuite } from '../../core/test/suite.ts'
import { closeHana, hana } from '../src/index.ts'

const TABLES = ['t_comment', 't_post', 't_user', 't_company']
const DDL = [
  'CREATE COLUMN TABLE "t_company" ("id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "name" NVARCHAR(100) NOT NULL)',
  'CREATE COLUMN TABLE "t_user" ("id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "name" NVARCHAR(100) NOT NULL, "age" INT, "company_id" BIGINT, "attrs" NVARCHAR(5000) NOT NULL, "created_at" TIMESTAMP NOT NULL)',
  'CREATE COLUMN TABLE "t_post" ("id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "user_id" BIGINT NOT NULL, "title" NVARCHAR(200) NOT NULL, "amount" DECIMAL(12,2) NOT NULL)',
  'CREATE COLUMN TABLE "t_comment" ("id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "post_id" BIGINT NOT NULL, "body" NVARCHAR(200) NOT NULL)',
]

const raw = process.env['EQTS_HANA_URL']

if (!raw) {
  describe('hana (live)', () => {
    it('skipped: set EQTS_HANA_URL to run', { skip: true }, () => {})
  })
} else {
  const url = new URL(raw)
  const options = { host: url.hostname, port: Number(url.port), user: decodeURIComponent(url.username), password: decodeURIComponent(url.password) }
  const admin = hana(options)
  const adapter = hana({ ...options, schema: 'EQTS' })
  after(() => {
    closeHana(admin)
    closeHana(adapter)
  })

  const ignoring = async (sql: string) => {
    try {
      await admin.driver.execute(sql, [])
    } catch {
      // HANA 没有 IF EXISTS：表或模式不存在时报错，忽略
    }
  }

  const open = async (): Promise<TestEnv> => {
    await ignoring('CREATE SCHEMA EQTS')
    for (const t of TABLES) await ignoring(`DROP TABLE EQTS."${t}"`)
    for (const statement of DDL) await adapter.driver.execute(statement, [])
    const statements: Statement[] = []
    return { db: createDb({ schema, adapter, log: (s) => statements.push(s) }), statements, adapter }
  }

  liveSuite(`hana ${url.port}`, open)
}
